#include <algorithm>
#include <cassert>
#include <cstddef>
#include <deque>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::deque<std::string> last_lines(std::istream& in, std::size_t k) {
    std::deque<std::string> kept;
    std::string line;
    // 한 줄을 읽을 때마다 최근 k줄만 소유합니다.
    while (std::getline(in, line)) {
        if (k == 0) continue;
        if (kept.size() == k) kept.pop_front();
        kept.push_back(line);
    }
    return kept;
}
int main(int argc, char** argv) {
    // 사용법: 프로그램 k < UTF-8-LF-텍스트파일
    if (argc != 2 || argv[1][0] == '\0') return 1;
    std::size_t k = 0;
    for (const char* p = argv[1]; *p != '\0'; ++p) {
        if (*p < '0' || *p > '9') return 1;
        const std::size_t digit = static_cast<std::size_t>(*p - '0');
        if (k > (10000U - digit) / 10U) return 1;
        k = k * 10U + digit;
    }
    const auto kept = last_lines(std::cin, k);
    if (std::cin.bad() || (!std::cin.eof() && std::cin.fail())) return 1;
    for (const auto& line : kept) std::cout << line << '\n';
    return std::cout ? 0 : 1;
}
